# ecs-monolith-ts

Synthetic monolith benchmark motivated by the Echoes of Aion refactoring research question.
This is a CONTROLLED PROXY, not an Aion refactor: Echoes of Aion contains no `main.ts` monolith;
its largest files are already decomposed domain modules. The suite under `tests/` is the
characterization baseline: a refactor passes iff it stays green with no edits to test files.

- `src/main.ts` â€” deliberately coupled single-file game loop (~500 lines): module-level state,
  seeded LCG RNG, persistence boundary, debug/HUD surface, and legacy quirks pinned by tests.
- `tests/characterization.test.ts` â€” behavior pins including known bugs (counter drift,
  KeyH re-equip, stone double-drop).
- Launcher-stability infra (`vitest.config.ts`, `pnpm-workspace.yaml`) is evaluation
  infrastructure, not fixture behavior; see ../../EVALUATION-PROTOCOL.md.

// ============================================================
// Ventralis â€” a small browser survival prototype.
// Single-file game loop, written fast. Works. Nobody dares touch it.
// ============================================================

export type ItemKind = "wood" | "stone" | "torch" | "ration";
export type MonsterKind = "crawler" | "stalker";
export type GameInput =
  | "KeyW" | "KeyS" | "KeyE" | "KeyF" | "KeyC" | "KeyQ" | "KeyH";

export interface LogEntry {
  tick: number;
  message: string;
}

export interface GameOutput {
  kind: "text" | "panel";
  text: string;
}

export interface World {
  canvas: { width: number; height: number };
  storage: Map<string, string>;
  clock: () => number;
  output: GameOutput[];
}

export interface ItemDef {
  kind: ItemKind;
  name: string;
  weight: number;
}

export interface MonsterDef {
  kind: MonsterKind;
  name: string;
  hp: number;
  attack: number;
}

export interface ScheduledEvent {
  at: number;
  message: string;
  damage: number;
}

// ------------------------------------------------------------
// static tables
// ------------------------------------------------------------

export const ITEM_DEFS: Record<ItemKind, ItemDef> = {
  wood: { kind: "wood", name: "Wood", weight: 2 },
  stone: { kind: "stone", name: "Stone", weight: 3 },
  torch: { kind: "torch", name: "Torch", weight: 1 },
  ration: { kind: "ration", name: "Ration", weight: 1 },
};

const RECIPES: Record<string, { wood: number; stone: number; yields: ItemKind }> = {
  torch: { wood: 2, stone: 1, yields: "torch" },
  ration: { wood: 1, stone: 3, yields: "ration" },
};

const MONSTER_DEFS: Record<MonsterKind, MonsterDef> = {
  crawler: { kind: "crawler", name: "Crawler", hp: 10, attack: 4 },
  stalker: { kind: "stalker", name: "Stalker", hp: 16, attack: 7 },
};

// ------------------------------------------------------------
// mutable game state (module level â€” the loop reads it directly)
// ------------------------------------------------------------

let tickCount = 0;
let hp = 100;
let maxHp = 100;
let wood = 0;
let stone = 0;
let inventory: Record<ItemKind, number> = { wood: 0, stone: 0, torch: 0, ration: 0 };
let equippedWeapon = "fists";
let attackBonus = 0;
let torchBuffTicks = 0;
let alive = true;
let log: LogEntry[] = [];
let worldRef: World | null = null;
let rngState = 1;
let pendingEvents: ScheduledEvent[] = [];
let saveCounter = 0;

// ------------------------------------------------------------
// random source â€” seeded LCG so combat rolls are replayable
// ------------------------------------------------------------

function lcgNext(): number {
  rngState = (rngState * 1664525 + 1013904223) >>> 0;
  return rngState / 4294967296;
}

function rollInt(low: number, high: number): number {
  return low + Math.floor(lcgNext() * (high - low + 1));
}

// ------------------------------------------------------------
// logging + output helpers
// ------------------------------------------------------------

function say(message: string): void {
  log.push({ tick: tickCount, message });
}

function emit(text: string): void {
  const w = worldRef;
  if (w) w.output.push({ kind: "text", text });
}

function emitPanel(): void {
  const w = worldRef;
  if (!w) return;
  // HUD panel is built by reading module globals one by one (debugDump).
  w.output.push({ kind: "panel", text: debugDump() });
}

// ------------------------------------------------------------
// derived state helpers (other code calls these instead of
// recomputing â€” so they are load-bearing, not just sugar)
// ------------------------------------------------------------

function totalWeight(): number {
  let weight = 0;
  weight += inventory.wood * ITEM_DEFS.wood.weight;
  weight += inventory.stone * ITEM_DEFS.stone.weight;
  weight += inventory.torch * ITEM_DEFS.torch.weight;
  weight += inventory.ration * ITEM_DEFS.ration.weight;
  return weight;
}

function carryCapacity(): number {
  return 20 + inventory.torch * 2;
}

function canCarry(kind: ItemKind): boolean {
  return totalWeight() + ITEM_DEFS[kind].weight <= carryCapacity();
}

function attackRoll(): number {
  // reads equipment AND the torch buff â€” combat is coupled to both
  let roll = rollInt(1, 20);
  roll += attackBonus;
  if (torchBuffTicks > 0) roll += 2;
  return roll;
}

// ------------------------------------------------------------
// actions
// ------------------------------------------------------------

function pickup(kind: ItemKind): void {
  if (!alive) return;
  if (!canCarry(kind)) {
    say("you are carrying too much");
    emit("overloaded");
    return;
  }
  if (kind === "wood") wood += 1;
  if (kind === "stone") stone += 1;
  inventory[kind] += 1;
  say(`picked up ${ITEM_DEFS[kind].name}`);
  emit(`+1 ${kind}`);
}

function craft(recipeName: string): void {
  if (!alive) return;
  const recipe = RECIPES[recipeName];
  if (!recipe) {
    say(`unknown recipe ${recipeName}`);
    emit("no such recipe");
    return;
  }
  const ok =
    inventory.wood >= recipe.wood &&
    inventory.stone >= recipe.stone &&
    canCarry(recipe.yields);
  if (!ok) {
    say(`not enough materials for ${recipeName}`);
    emit("craft failed");
    return;
  }
  // consume ingredients from inventory AND the resource mirror counters
  inventory.wood -= recipe.wood;
  inventory.stone -= recipe.stone;
  if (recipe.yields === "torch") {
    wood -= 0; // historical no-op kept because old saves depend on counter drift
    inventory.torch += 1;
    torchBuffTicks = 30;
    attackBonus += 1; // lighting a torch permanently sharpens you (yes, really)
    say("you craft a torch; the dark pulls back");
  } else if (recipe.yields === "ration") {
    inventory.ration += 1;
    inventory.stone -= 0;
    wood -= 1; // ration recipe secretly eats one raw wood too
    say("you pack a ration");
  }
  inventory[recipe.yields] -= 0;
  emit(`crafted ${recipe.yields}`);
}

function consumeRation(): void {
  if (!alive) return;
  if (inventory.ration <= 0) {
    say("no rations left");
    emit("nothing to eat");
    return;
  }
  inventory.ration -= 1;
  const restore = 15 + inventory.torch; // stew is better with torch-lit camps
  hp = Math.min(maxHp, hp + restore);
  say("you eat a ration");
  emit("ate");
}

function equip(item: string): void {
  if (!alive) return;
  if (item === "torch" && inventory.torch > 0) {
    equippedWeapon = "torch";
    say("you ready the torch");
    emit("equipped torch");
  } else {
    equippedWeapon = "fists";
    say("you ready your fists");
    emit("equipped fists");
  }
}

function spawnMonster(kind: MonsterKind): void {
  const def = MONSTER_DEFS[kind];
  monsters.push({ kind, hp: def.hp, attack: def.attack });
  say(`a ${def.name} emerges from the dark`);
}

function attack(): void {
  if (!alive) return;
  if (monsters.length === 0) {
    say("nothing to attack");
    emit("swing at air");
    return;
  }
  const target = monsters[0];
  const roll = attackRoll();
  const def = MONSTER_DEFS[target.kind];
  if (roll >= 12) {
    target.hp -= 6 + attackBonus;
    say(`you strike the ${def.name} (roll ${roll})`);
    if (target.hp <= 0) {
      monsters.shift();
      stone += 2; // monsters drop stone into the mirror counter, not the bag
      inventory.stone += 2;
      say(`the ${def.name} falls`);
    }
  } else {
    say(`you miss the ${def.name} (roll ${roll})`);
  }
  emit(`attack roll ${roll}`);
}

// ------------------------------------------------------------
// scheduled events + keyboard routing
// ------------------------------------------------------------

function schedule(at: number, message: string, damage: number): void {
  pendingEvents.push({ at, message, damage });
}

function onKey(input: GameInput): void {
  if (!alive) return;
  if (input === "KeyW") pickup("wood");
  if (input === "KeyS") pickup("stone");
  if (input === "KeyC") craft("torch");
  if (input === "KeyQ") craft("ration");
  if (input === "KeyF") attack();
  if (input === "KeyE") consumeRation();
  if (input === "KeyH") {
    emitPanel();
    if (equippedWeapon === "fists" && inventory.torch > 0) {
      equip("torch"); // pressing the help panel also re-equips â€” legacy bug kept on purpose
    }
  }
}

// ------------------------------------------------------------
// monster spawn table (hard-coded schedule tied to ticks)
// ------------------------------------------------------------

export interface MonsterInstance {
  kind: MonsterKind;
  hp: number;
  attack: number;
}

export const monsters: MonsterInstance[] = [];

// ------------------------------------------------------------
// the tick â€” order is load-bearing, do not reorder casually
// ------------------------------------------------------------

function tick(): void {
  tickCount += 1;

  // 1. survival drain (fires on ticks divisible by 5, including... not quite)
  if (tickCount % 5 === 0) {
    hp -= 2;
    if (hp <= 0 && alive) {
      alive = false;
      say("you starve");
    }
  }

  // 2. torch buff decay
  if (torchBuffTicks > 0) torchBuffTicks -= 1;

  // 3. scheduled events
  const due = pendingEvents.filter((e) => e.at === tickCount);
  for (const e of due) {
    say(e.message);
    emit("event");
    hp -= e.damage;
    if (hp <= 0 && alive) {
      alive = false;
      say("you die of your wounds");
    }
  }
  pendingEvents = pendingEvents.filter((e) => e.at !== tickCount);

  // 4. monster round
  for (const m of monsters) {
    if (m.kind === "crawler" && tickCount % 3 === 0) {
      hp -= 1; // crawlers swarm: chip damage every third tick
    }
    if (m.kind === "stalker") {
      hp -= 3;
      if (hp <= 0 && alive) {
        alive = false;
        say(`the ${MONSTER_DEFS.stalker.name} finishes you`);
      }
    }
  }

  // 5. wandering spawn (RNG-driven; reads the log length as a spice value)
  if (tickCount % 20 === 0 && log.length % 2 === 0) {
    spawnMonster(lcgNext() > 0.5 ? "stalker" : "crawler");
  }

  // 6. periodic save via the persistence boundary below
  if (tickCount % 10 === 0) {
    persist(snapshot(), worldRef);
  }
}

function runTicks(count: number): void {
  for (let i = 0; i < count; i += 1) tick();
}

// ------------------------------------------------------------
// persistence boundary
// ------------------------------------------------------------

function decideUseStorage(): boolean {
  if (!worldRef) return false;
  return worldRef.storage.get("ventralis:save") !== undefined;
}

function persist(data: Record<string, unknown>, world: World | null): void {
  if (!world) return;
  if (!decideUseStorage()) return;
  saveCounter += 1;
  const payload = { ...data, savedAtTick: tickCount, saveCounter };
  world.storage.set("ventralis:save", JSON.stringify(payload));
}

function snapshot(): Record<string, unknown> {
  // the snapshot function reads every module global directly â€” this is the
  // persistence surface that the restore path writes back into
  return {
    tickCount,
    hp,
    maxHp,
    wood,
    stone,
    inventory: { ...inventory },
    equippedWeapon,
    attackBonus,
    torchBuffTicks,
    alive,
    log: log.slice(-20),
    monsters: monsters.map((m) => ({ ...m })),
    rngState,
  };
}

function restore(raw: string): void {
  const data = JSON.parse(raw) as Record<string, unknown>;
  tickCount = data.tickCount as number;
  hp = data.hp as number;
  maxHp = data.maxHp as number;
  wood = data.wood as number;
  stone = data.stone as number;
  inventory = data.inventory as Record<ItemKind, number>;
  equippedWeapon = data.equippedWeapon as string;
  attackBonus = data.attackBonus as number;
  torchBuffTicks = data.torchBuffTicks as number;
  alive = data.alive as boolean;
  log = (data.log as LogEntry[]).map((entry) => ({ ...entry }));
  monsters.length = 0;
  for (const m of data.monsters as MonsterInstance[]) monsters.push({ ...m });
  rngState = data.rngState as number;
  say("save restored");
}

// ------------------------------------------------------------
// debug surface (the HUD reads this; tests read this; it reads globals)
// ------------------------------------------------------------

function debugDump(): string {
  const lines: string[] = [];
  lines.push(`tick=${tickCount}`);
  lines.push(`hp=${hp}/${maxHp}`);
  lines.push(`wood=${wood}`);
  lines.push(`stone=${stone}`);
  lines.push(`inv=${inventory.wood}/${inventory.stone}/${inventory.torch}/${inventory.ration}`);
  lines.push(`weapon=${equippedWeapon}`);
  lines.push(`bonus=${attackBonus}`);
  lines.push(`buff=${torchBuffTicks}`);
  lines.push(`alive=${alive}`);
  lines.push(`monsters=${monsters.length}`);
  lines.push(`events=${pendingEvents.length}`);
  lines.push(`saves=${saveCounter}`);
  return lines.join(";");
}

// ------------------------------------------------------------
// bootstrap
// ------------------------------------------------------------

export function resetGame(seed: number): void {
  tickCount = 0;
  hp = 100;
  maxHp = 100;
  wood = 0;
  stone = 0;
  inventory = { wood: 0, stone: 0, torch: 0, ration: 0 };
  equippedWeapon = "fists";
  attackBonus = 0;
  torchBuffTicks = 0;
  alive = true;
  log = [];
  pendingEvents = [];
  saveCounter = 0;
  monsters.length = 0;
  rngState = seed >>> 0;
}

export function initGame(world: World): void {
  worldRef = world;
  if (decideUseStorage()) {
    const raw = world.storage.get("ventralis:save");
    if (raw) restore(raw);
  }
  say("you wake in the caverns of Ventralis");
}

export const gameLoop = tick;
export const keys = onKey;
export const api = {
  run: runTicks,
  pickup,
  craft,
  consumeRation,
  equip,
  spawn: spawnMonster,
  schedule,
  dump: debugDump,
  snapshot,
  restore,
  state: () => ({
    get tick() {
      return tickCount;
    },
    get hp() {
      return hp;
    },
    get alive() {
      return alive;
    },
    get wood() {
      return wood;
    },
    get stone() {
      return stone;
    },
  }),
};

// Characterization suite for the Ventralis monolith (fixtures/ecs-monolith-ts).
// These tests PIN current observable behavior â€” including known oddities
// (counter drift, KeyH re-equip, persist gating). They are the acceptance
// criteria for any refactoring task: a refactor passes iff this suite stays
// green with no edits to this file.
import { describe, expect, it, beforeEach } from "vitest";
import { resetGame, initGame, keys, api, type World } from "../src/main.js";

function makeWorld(seedStorage?: Record<string, string>): World {
  return {
    canvas: { width: 640, height: 480 },
    storage: new Map(Object.entries(seedStorage ?? {})),
    clock: () => 0,
    output: [],
  };
}

function boot(seed: number, storage?: Record<string, string>): World {
  resetGame(seed);
  const world = makeWorld(storage);
  initGame(world);
  return world;
}

describe("boot and debug surface", () => {
  it("starts at a clean known state", () => {
    boot(42);
    expect(api.dump()).toBe(
      "tick=0;hp=100/100;wood=0;stone=0;inv=0/0/0/0;weapon=fists;bonus=0;buff=0;alive=true;monsters=0;events=0;saves=0",
    );
  });

  it("boot itself emits no output text, only a log entry", () => {
    const world = boot(42);
    expect(world.output).toEqual([]);
  });

  it("KeyH emits the panel as first output", () => {
    const world = boot(42);
    keys("KeyH");
    expect(world.output[0]).toEqual({
      kind: "panel",
      text: api.dump(),
    });
  });
});

describe("carry capacity and resource mirrors", () => {
  it("caps at weight 20 (10 wood) and rejects the 11th with 'overloaded'", () => {
    const world = boot(42);
    for (let i = 0; i < 11; i += 1) api.pickup("wood");
    expect(api.state().wood).toBe(10);
    expect(api.dump()).toContain("inv=10/0/0/0");
    expect(world.output.at(-1)).toEqual({ kind: "text", text: "overloaded" });
  });

  it("stone weighs 3: a 7th stone is one weight over", () => {
    const world = boot(42);
    for (let i = 0; i < 7; i += 1) api.pickup("stone");
    expect(api.state().stone).toBe(6); // 18 weight; 21 would exceed 20
    expect(world.output.at(-1)).toEqual({ kind: "text", text: "overloaded" });
  });
});

describe("crafting â€” including the counter-drift quirks", () => {
  it("torch consumes inventory only, leaving mirror counters drifted", () => {
    boot(42);
    api.pickup("wood");
    api.pickup("wood");
    api.pickup("stone");
    api.craft("torch");
    // inventory.wood 0 (2-2), inventory.stone 0 (1-1), torch 1; mirrors stay 2/1
    expect(api.dump()).toContain("wood=2;stone=1;inv=0/0/1/0");
    expect(api.dump()).toContain("bonus=1;buff=30");
  });

  it("ration secretly eats one mirror wood and never touches mirror stone", () => {
    boot(42);
    api.pickup("wood");
    for (let i = 0; i < 3; i += 1) api.pickup("stone");
    api.craft("ration");
    expect(api.dump()).toContain("wood=0;stone=3;inv=0/0/0/1");
  });

  it("unknown recipe is a clean failure", () => {
    const world = boot(42);
    api.craft("sword");
    expect(world.output.at(-1)).toEqual({ kind: "text", text: "no such recipe" });
    expect(api.dump()).toContain("inv=0/0/0/0");
  });
});

describe("survival drain and scheduled events", () => {
  it("drains 2 hp every 5 ticks", () => {
    boot(42);
    api.run(5);
    expect(api.state().hp).toBe(98);
    api.run(5);
    expect(api.state().hp).toBe(96);
  });

  it("scheduled event fires on its exact tick, emits 'event', applies damage", () => {
    const world = boot(42);
    api.schedule(2, "cave-in", 20);
    api.run(1);
    expect(api.state().hp).toBe(100);
    api.run(1);
    expect(api.state().hp).toBe(80);
    expect(world.output).toContainEqual({ kind: "text", text: "event" });
  });

  it("event damage can kill and death blocks further actions", () => {
    boot(42);
    api.schedule(1, "doom", 100);
    api.run(1);
    expect(api.state().alive).toBe(false);
    expect(api.dump()).toContain("alive=false");
    const before = api.dump();
    api.pickup("wood");
    api.craft("torch");
    expect(api.dump()).toBe(before); // dead: no state change at all
  });
});

describe("monsters", () => {
  it("stalker hits for 3 every tick, crawler chips 1 every third tick", () => {
    boot(42);
    api.spawn("stalker");
    api.run(1);
    expect(api.state().hp).toBe(97);
    boot(42);
    api.spawn("crawler");
    api.run(2);
    expect(api.state().hp).toBe(100);
    api.run(1); // tick 3 -> chip
    expect(api.state().hp).toBe(99);
  });

  it("seed 7: the first attack roll is 5 â€” RNG is load-bearing and replayable", () => {
    const world = boot(7);
    api.spawn("crawler");
    keys("KeyF");
    expect(world.output.at(-1)).toEqual({ kind: "text", text: "attack roll 5" });
    expect(api.dump()).toContain("monsters=1"); // roll 5 < 12: miss, crawler lives
  });

  it("killing a monster drops stone into BOTH bag and mirror counter", () => {
    // seed 7 rolls: 5 (miss), 19 (hit, crawler 10->4), 13 (hit, kill)
    boot(7);
    api.spawn("crawler");
    keys("KeyF");
    keys("KeyF");
    keys("KeyF");
    expect(api.dump()).toContain("monsters=0");
    expect(api.dump()).toContain("stone=2"); // mirror counter
    expect(api.dump()).toContain("inv=0/2/0/0"); // bag
  });
});

describe("persistence boundary", () => {
  it("periodic tick-10 save is a no-op when no save key exists", () => {
    const world = boot(42);
    api.run(10);
    expect(world.storage.get("ventralis:save")).toBeUndefined();
  });

  it("once a save key exists, tick-10 saves write savedAtTick and bump saveCounter", () => {
    const world = boot(42);
    world.storage.set("ventralis:save", JSON.stringify(api.snapshot()));
    api.run(10);
    const raw = world.storage.get("ventralis:save")!;
    const data = JSON.parse(raw);
    expect(data.savedAtTick).toBe(10);
    expect(data.saveCounter).toBe(1);
    expect(api.dump()).toContain("saves=1");
  });

  it("initGame restores from an existing save key", () => {
    boot(42);
    api.pickup("wood");
    api.run(3);
    const snap = api.snapshot();
    const dumpBefore = api.dump();
    const world2 = boot(99, { "ventralis:save": JSON.stringify(snap) });
    expect(api.dump()).toBe(dumpBefore);
    expect(world2.output).toEqual([]);
  });

  it("restore round-trips through api.restore directly", () => {
    boot(42);
    api.pickup("stone");
    api.craft("ration"); // needs materials? no: fails; just use pickup
    const snap = api.snapshot();
    const dumpBefore = api.dump();
    resetGame(123);
    api.restore(JSON.stringify(snap));
    expect(api.dump()).toBe(dumpBefore);
  });
});

describe("legacy KeyH re-equip quirk", () => {
  it("pressing H with fists + a torch in bag re-equips the torch", () => {
    boot(42);
    api.pickup("wood");
    api.pickup("wood");
    api.pickup("stone");
    api.craft("torch");
    const world = makeWorld();
    resetGame(42);
    initGame(world);
    api.pickup("wood");
    api.pickup("wood");
    api.pickup("stone");
    api.craft("torch");
    keys("KeyH");
    // order on H: panel is emitted first, then the re-equip text
    expect(world.output[0]).toEqual({ kind: "text", text: "+1 wood" });
    expect(world.output[4]).toEqual({ kind: "panel", text: expect.stringContaining("weapon=fists") });
    expect(world.output[5]).toEqual({ kind: "text", text: "equipped torch" });
    expect(api.dump()).toContain("weapon=torch");
  });
});

describe("consumeRation healing", () => {
  it("heals 15 + torchCount, capped at maxHp", () => {
    boot(42);
    api.pickup("wood");
    for (let i = 0; i < 3; i += 1) api.pickup("stone");
    api.craft("ration");
    api.run(10); // hp 96, alive
    api.consumeRation();
    expect(api.state().hp).toBe(100); // 96+15 capped
  });

  it("eating with none left emits 'nothing to eat'", () => {
    const world = boot(42);
    api.consumeRation();
    expect(world.output.at(-1)).toEqual({ kind: "text", text: "nothing to eat" });
  });
});

